from fractions import Fraction
from sympy import symbols, expand
x = symbols("x")

def as_sympy(p):
    # the polynomial with coefficient list p, leading coefficient first
    total = 0
    for c in p:
        total = total * x + c
    return expand(total)

def read_list():
    m = int(input())
    p = []
    for k in range(m):
        p.append(int(input()))
    return p

def divide(p, d):
    r = []
    for c in p:
        r.append(Fraction(c))
    q = []
    for k in range(len(p) - len(d) + 1):
        t = r[k] / d[0]
        q.append(t)
        for i in range(len(d)):
            r[k + i] = r[k + i] - t * d[i]
    rem = []
    for k in range(len(p) - len(d) + 1, len(p)):
        rem.append(r[k])
    return q, rem

n = int(input())
for i in range(n):
    p = read_list()
    d = read_list()
    q, r = divide(p, d)
    print(f"quotient {as_sympy(q)}, remainder {as_sympy(r)}")
    print(f"check: {expand(as_sympy(d) * as_sympy(q) + as_sympy(r)) == as_sympy(p)}")

