from fractions import Fraction
from sympy import symbols, factor
x = symbols("x")

def remainder(p, c):
    total = 0
    for a in p:
        total = total * c + a
    return total

def search(case, p):
    print(case)
    a0 = p[len(p) - 1]
    an = p[0]
    print(f"  divisors r of a0 = {a0} over divisors s of an = {an}")
    cands = []
    for r in range(1, abs(a0) + 1):
        if a0 % r == 0:
            for s in range(1, abs(an) + 1):
                if an % s == 0:
                    for v in [Fraction(r, s), Fraction(-r, s)]:
                        if v not in cands:
                            cands.append(v)
    print(f"  {len(cands)} candidates")
    found = 0
    for v in cands:
        if remainder(p, v) == 0:
            print(f"  p({v}) = 0: a root")
            found = found + 1
    if found == 0:
        print("  no candidate is a root: no rational roots")
    total = 0
    for a in p:
        total = total * x + a
    print(f"  sympy: {factor(total)}")

search("Case 1 · fraction roots: 2x^3 - 3x^2 - 3x + 2", [2, -3, -3, 2])
search("Case 2 · leading coefficient 1: x^3 - 6x^2 + 11x - 6", [1, -6, 11, -6])
search("Case 3 · no rational roots: x^2 - 2", [1, 0, -2])
search("Case 4 · the upside-down trap: 3x^2 - 4x + 1", [3, -4, 1])
search("Case 5 · a word problem: x^3 + 3x^2 + 2x - 60", [1, 3, 2, -60])

